package com.oms.inventory.service.impl;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import javax.annotation.Resource;
import java.math.BigDecimal;
import java.util.*;
import static com.oms.inventory.service.impl.StockProcessService.*;

/** Physical inventory and transfer transit have separate ledgers. All mutations lock sorted SKU mutexes first. */
@Service public class StockMovementService {
 @Resource JdbcTemplate jdbc;
 @Resource InventoryMutationService mutations;
 private void need(boolean b,String m){if(!b)throw new IllegalArgumentException(m);}
 private Map<String,Object> one(String sql,Object...args){List<Map<String,Object>> r=jdbc.queryForList(sql,args);need(r.size()==1,"库存来源不存在或不属于当前公司");return r.get(0);}
 private String hash(Object value){try{byte[] b=java.security.MessageDigest.getInstance("SHA-256").digest(encode(value).getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v));return s.toString();}catch(Exception e){throw new IllegalArgumentException(e);}}
 private void identity(String c,String sn){need(c!=null&&c.matches("[A-Z0-9_-]{1,64}")&&sn.matches("(DB|TZ)[A-Za-z0-9_-]{1,60}"),"公司或库存业务单号无效");}
 private void lock(String c,List<Map<String,Object>> lines){TreeSet<String> skus=new TreeSet<>();for(Map<String,Object> l:lines)skus.add(s(l,"sku_sn"));for(String sku:skus)one("SELECT * FROM oms_inventory WHERE company_code=? AND sku_sn=? FOR UPDATE",c,sku);}
 private String marks(int count){return String.join(",",Collections.nCopies(count,"?"));}
 @SuppressWarnings("unchecked") private List<String> strings(Object o,int max){need(o instanceof List&&!((List<?>)o).isEmpty()&&((List<?>)o).size()<=max,"库存范围为空或超过上限");List<String> r=new ArrayList<>();for(Object a:(List<?>)o){String v=Objects.toString(a,"").trim();need(!v.isEmpty()&&v.length()<=128&&!r.contains(v),"库存范围重复或无效");r.add(v);}Collections.sort(r);return r;}
 /** A repeatable local read gives batch versions and SKU mutex versions for later compare-and-set adjustment. */
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ,timeout=20)
 public Map<String,Object> snapshot(String c,Map<String,Object> cmd){
  List<String> stores=strings(cmd.get("stores"),50),skus=strings(cmd.get("skus"),100);List<Object>a=new ArrayList<>();a.add(c);a.addAll(stores);a.addAll(skus);
  List<Map<String,Object>> batches=jdbc.queryForList("SELECT id,sku_sn,store_code,batch_code,transaction_price,zp_actual_number,cp_actual_number,zp_available_number,cp_available_number,zp_lock_number,cp_lock_number,version FROM wms_inventory_batch WHERE company_code=? AND store_code IN("+marks(stores.size())+") AND sku_sn IN("+marks(skus.size())+") ORDER BY sku_sn,store_code,id LIMIT 5001",a.toArray());need(batches.size()<=5000,"所选库存超过5000批次，请缩小SKU范围");
  List<Object>b=new ArrayList<>();b.add(c);b.addAll(skus);List<Map<String,Object>> totals=jdbc.queryForList("SELECT sku_sn,total_stock,available_stock,reserved_stock,allocated_stock,frozen_stock,version FROM oms_inventory WHERE company_code=? AND sku_sn IN("+marks(skus.size())+") ORDER BY sku_sn",b.toArray());
  List<Map<String,Object>> transit=jdbc.queryForList("SELECT sku_sn,SUM(out_quantity-in_quantity-recovered_quantity) transit_quantity FROM oms_stock_transfer_line WHERE company_code=? AND sku_sn IN("+marks(skus.size())+") GROUP BY sku_sn",b.toArray());
  return map("stores",stores,"skus",skus,"batches",batches,"totals",totals,"transit",transit,"snapshot_at",java.time.LocalDateTime.now().toString());
 }
 /** Keyset discovery reads this company and these stores only; zero/frozen/held stock records remain in scope. */
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ,timeout=20)
 public Map<String,Object> discover(String c,Map<String,Object> cmd){
  List<String>stores=strings(cmd.get("stores"),50);long cursor=n(cmd,"cursor"),maximum=n(cmd,"maximum");need(cursor>=0&&maximum>=0,"库存发现游标无效");List<Object> args=new ArrayList<>();args.add(c);args.addAll(stores);
  if(!Boolean.TRUE.equals(cmd.get("started")))maximum=jdbc.queryForObject("SELECT COALESCE(MAX(id),0) FROM wms_inventory WHERE company_code=? AND store_code IN("+marks(stores.size())+")",Long.class,args.toArray());
  args.add(cursor);args.add(maximum);List<Map<String,Object>> rows=jdbc.queryForList("SELECT id,sku_sn FROM wms_inventory WHERE company_code=? AND store_code IN("+marks(stores.size())+") AND id>? AND id<=? ORDER BY id LIMIT 100",args.toArray());
  long next=rows.isEmpty()?cursor:n(rows.get(rows.size()-1),"id");return map("rows",rows,"maximum",maximum,"cursor",next,"done",rows.size()<100||next>=maximum);
 }
 @Transactional(readOnly=true,timeout=20)
 public Map<String,Object> checkSearch(String c,Map<String,Object>cmd){List<String>stores=strings(cmd.get("stores"),50);String keyword=Objects.toString(cmd.get("keyword"),"").trim();need(!keyword.isEmpty()&&keyword.length()<=128,"请输入SKU编码前缀");List<Object>a=new ArrayList<>();a.add(c);a.addAll(stores);a.add(keyword.replace("=","==").replace("%","=%").replace("_","=_")+"%");return map("rows",jdbc.queryForList("SELECT DISTINCT sku_sn FROM wms_inventory WHERE company_code=? AND store_code IN("+marks(stores.size())+") AND sku_sn LIKE ? ESCAPE '=' ORDER BY sku_sn LIMIT 30",a.toArray()));}
 public Map<String,Object> report(String c,String sn){identity(c,sn);Map<String,Object> d=one("SELECT * FROM oms_stock_transfer WHERE company_code=? AND document_sn=?",c,sn);d.put("lines",jdbc.queryForList("SELECT *,(out_quantity-in_quantity-recovered_quantity) transit_quantity FROM oms_stock_transfer_line WHERE company_code=? AND document_sn=? ORDER BY line_key",c,sn));return d;}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED,timeout=30)
 public Map<String,Object> execute(String c,String action,Map<String,Object> original){
  Map<String,Object> cmd=object(encode(original));String sn=s(cmd,"document_sn");identity(c,sn);need(Arrays.asList("reserve","out","in","recover","release","adjust").contains(action),"库存动作无效");
  if(action.equals("adjust")){adjust(c,sn,cmd);return map("posted",true);}
  List<Map<String,Object>> lines=action.equals("reserve")?rows(cmd.get("lines")):jdbc.queryForList("SELECT * FROM oms_stock_transfer_line WHERE company_code=? AND document_sn=? ORDER BY line_key",c,sn);need(!lines.isEmpty()&&lines.size()<=200,"调拨库存明细须为1至200行");lock(c,lines);
  if(action.equals("reserve"))reserve(c,sn,cmd,lines);else{
   Map<String,Object> d=one("SELECT * FROM oms_stock_transfer WHERE company_code=? AND document_sn=? FOR UPDATE",c,sn);lines=jdbc.queryForList("SELECT * FROM oms_stock_transfer_line WHERE company_code=? AND document_sn=? ORDER BY line_key",c,sn);String event=action+"/"+s(cmd,"message_id");need(!s(cmd,"message_id").isEmpty()&&event.length()<=128,"库存事件身份缺失");if(prior(c,sn,event,cmd))return report(c,sn);
   if(action.equals("release"))release(c,sn,cmd,lines);else post(c,sn,action,cmd,d,lines);record(c,sn,event,cmd);
  }
  return report(c,sn);
 }
 private boolean prior(String c,String sn,String event,Map<String,Object>cmd){List<String> h=jdbc.queryForList("SELECT payload_hash FROM oms_stock_movement_event WHERE company_code=? AND document_sn=? AND message_id=?",String.class,c,sn,event);if(h.isEmpty())return false;need(hash(cmd).equals(h.get(0)),"相同库存事件内容发生变化");return true;}
 private void record(String c,String sn,String event,Map<String,Object>cmd){jdbc.update("INSERT INTO oms_stock_movement_event(company_code,document_sn,message_id,payload_hash) VALUES (?,?,?,?)",c,sn,event,hash(cmd));}
 private Map<String,String> versions(Map<String,Object> snapshot){Map<String,String>r=new TreeMap<>();for(Map<String,Object>b:rows(snapshot.get("batches")))r.put("B/"+n(b,"id"),String.valueOf(n(b,"version")));for(Map<String,Object>b:rows(snapshot.get("totals")))r.put("S/"+s(b,"sku_sn"),String.valueOf(n(b,"version")));return r;}
 private void consistent(String c,String sku,String store){Map<String,Object>w=one("SELECT * FROM wms_inventory WHERE company_code=? AND sku_sn=? AND store_code=? FOR UPDATE",c,sku,store);Map<String,Object>b=one("SELECT COALESCE(SUM(zp_actual_number),0) za,COALESCE(SUM(cp_actual_number),0) ca,COALESCE(SUM(zp_available_number),0) zv,COALESCE(SUM(cp_available_number),0) cv,COALESCE(SUM(zp_lock_number),0) zl,COALESCE(SUM(cp_lock_number),0) cl FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=?",c,sku,store);for(String p:Arrays.asList("z","c")){String q=p.equals("z")?"zp":"cp";need(n(w,q+"_actual_number")==n(b,p+"a")&&n(w,q+"_available_number")==n(b,p+"v")&&n(w,q+"_lock_number")==n(b,p+"l")&&n(b,p+"a")==n(b,p+"v")+n(b,p+"l"),"仓库与批次库存不一致，请先核对");}}
 private Map<String,Object> batch(String c,Object id){return one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=? FOR UPDATE",c,id);}
 private void change(String c,Map<String,Object>b,String type,long physical,long free,long held){String p=type.equals("ZP")?"zp":"cp";need(n(b,p+"_actual_number")+physical>=0&&n(b,p+"_available_number")+free>=0&&n(b,p+"_lock_number")+held>=0,"原批次实物、可用或占用余额不足");jdbc.update("UPDATE wms_inventory_batch SET "+p+"_actual_number="+p+"_actual_number+?,"+p+"_available_number="+p+"_available_number+?,"+p+"_lock_number="+p+"_lock_number+?,version=version+1 WHERE company_code=? AND id=?",physical,free,held,c,b.get("id"));jdbc.update("UPDATE wms_inventory SET "+p+"_actual_number="+p+"_actual_number+?,"+p+"_available_number="+p+"_available_number+?,"+p+"_lock_number="+p+"_lock_number+?,version=version+1 WHERE company_code=? AND sku_sn=? AND store_code=?",physical,free,held,c,b.get("sku_sn"),b.get("store_code"));}
 private void summary(String c,String sku,long physical,long free,long allocated,long frozen){Map<String,Object>d=one("SELECT * FROM oms_inventory WHERE company_code=? AND sku_sn=?",c,sku);need(n(d,"total_stock")+physical>=0&&n(d,"available_stock")+free>=0&&n(d,"allocated_stock")+allocated>=0&&n(d,"frozen_stock")+frozen>=0,"公司库存余额不足");jdbc.update("UPDATE oms_inventory SET total_stock=total_stock+?,available_stock=available_stock+?,allocated_stock=allocated_stock+?,frozen_stock=frozen_stock+?,version=version+1 WHERE company_code=? AND sku_sn=?",physical,free,allocated,frozen,c,sku);}
 private void journal(String c,String sn,String event,String op,Map<String,Object>b,String type,long q,String actor){Map<String,Object>after=batch(c,b.get("id"));List<Object>a=new ArrayList<>(Arrays.asList(c,b.get("store_code"),b.get("sku_sn"),b.get("id"),b.get("batch_code"),type,op,hash(sn+"/"+event+"/"+op+"/"+b.get("id")+"/"+type),sn,q,"跨实仓调拨或盘点差异审核",0,actor));StringBuilder cols=new StringBuilder("company_code,store_code,sku_sn,batch_id,batch_code,inventory_type,operation_type,request_id,relation_sn,change_quantity,change_reason,operator_id,operator_name");for(String k:InventoryQueryService.QUANTITIES){cols.append(",old_").append(k).append(",new_").append(k);a.add(b.get(k));a.add(after.get(k));}jdbc.update("INSERT INTO wms_inventory_change_history("+cols+") VALUES ("+marks(a.size())+")",a.toArray());jdbc.update("INSERT INTO oms_allocation_stock_signal(company_code,sku_sn,store_code) VALUES (?,?,?) ON DUPLICATE KEY UPDATE revision=revision+1,update_time=NOW()",c,b.get("sku_sn"),b.get("store_code"));}
 private void reserve(String c,String sn,Map<String,Object>cmd,List<Map<String,Object>>lines){List<String>old=jdbc.queryForList("SELECT request_hash FROM oms_stock_transfer WHERE company_code=? AND document_sn=? FOR UPDATE",String.class,c,sn);if(!old.isEmpty()){need(hash(cmd).equals(old.get(0)),"同一调拨占用请求内容变化");return;}jdbc.update("INSERT INTO oms_stock_transfer(company_code,document_sn,request_hash) VALUES (?,?,?)",c,sn,hash(cmd));Set<Long>keys=new HashSet<>();
  for(Map<String,Object>l:lines){String sku=s(l,"sku_sn"),source=s(l,"source_store"),target=s(l,"target_store"),type=s(l,"inventory_type");long q=n(l,"quantity"),key=n(l,"line_key");need(q>0&&q<=100000000&&key>0&&keys.add(key)&&!source.equals(target)&&!source.isEmpty()&&!target.isEmpty()&&Arrays.asList("ZP","CP").contains(type),"调拨来源、数量或正次品无效");consistent(c,sku,source);Map<String,Object>b=batch(c,l.get("source_batch_id"));need(sku.equals(s(b,"sku_sn"))&&source.equals(s(b,"store_code"))&&s(l,"batch_code").equals(s(b,"batch_code"))&&new BigDecimal(l.get("unit_cost").toString()).compareTo(new BigDecimal(b.get("transaction_price").toString()))==0,"原库存批次或成本变化，请重新选择");if(type.equals("ZP"))need(mutations.allocationAvailable(c,sku,Collections.singletonList(source))>=q,"扣除订单预占、福袋保障及渠道承诺后可调拨库存不足");change(c,b,type,0,-q,q);summary(c,sku,0,type.equals("ZP")?-q:0,q,type.equals("CP")?-q:0);jdbc.update("INSERT INTO oms_stock_transfer_line(company_code,document_sn,line_key,source_batch_id,sku_sn,source_store,target_store,batch_code,inventory_type,unit_cost,stock_unit,quantity) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",c,sn,key,b.get("id"),sku,source,target,b.get("batch_code"),type,b.get("transaction_price"),s(l,"stock_unit"),q);journal(c,sn,"HOLD/"+key,"TRANSFER_HOLD",b,type,q,s(cmd,"actor"));}
 }
 private void release(String c,String sn,Map<String,Object>cmd,List<Map<String,Object>>lines){for(Map<String,Object>l:lines){long q=n(l,"quantity")-n(l,"out_quantity")-n(l,"released_quantity");if(q==0)continue;Map<String,Object>b=batch(c,l.get("source_batch_id"));consistent(c,s(l,"sku_sn"),s(l,"source_store"));String type=s(l,"inventory_type");change(c,b,type,0,q,-q);summary(c,s(l,"sku_sn"),0,type.equals("ZP")?q:0,-q,type.equals("CP")?q:0);jdbc.update("UPDATE oms_stock_transfer_line SET released_quantity=released_quantity+? WHERE company_code=? AND document_sn=? AND line_key=?",q,c,sn,l.get("line_key"));journal(c,sn,"RELEASE/"+l.get("line_key"),"TRANSFER_RELEASE",b,type,q,s(cmd,"actor"));OrderStockService.replanPending(jdbc,c,s(l,"sku_sn"));}jdbc.update("UPDATE oms_stock_transfer SET state='STOPPED' WHERE company_code=? AND document_sn=?",c,sn);}
 private void post(String c,String sn,String action,Map<String,Object>cmd,Map<String,Object>d,List<Map<String,Object>>holds){Map<Long,Map<String,Object>>index=new HashMap<>();for(Map<String,Object>l:holds)index.put(n(l,"line_key"),l);Set<Long>seen=new HashSet<>();List<Map<String,Object>>facts=rows(cmd.get("lines"));need(facts.size()<=200,"实物回传行数超过上限");for(Map<String,Object>f:facts){long key=n(f,"line_key"),q=n(f,"quantity");Map<String,Object>h=index.get(key);need(h!=null&&seen.add(key)&&q>=0,"原调拨行或增量数量无效");if(q==0)continue;String type=s(h,"inventory_type"),sku=s(h,"sku_sn");need(sku.equals(s(f,"sku_sn"))&&s(h,"batch_code").equals(s(f,"batch_code"))&&type.equals(s(f,"inventory_type")),"调拨SKU、批次或质量必须沿用原行");
   if(action.equals("out")){need(s(d,"state").equals("HELD")&&q<=n(h,"quantity")-n(h,"out_quantity")-n(h,"released_quantity"),"出库超过本调拨原占用余额或未出库余额已停止");Map<String,Object>b=batch(c,h.get("source_batch_id"));consistent(c,sku,s(h,"source_store"));change(c,b,type,-q,0,-q);summary(c,sku,-q,0,-q,0);jdbc.update("UPDATE oms_stock_transfer_line SET out_quantity=out_quantity+? WHERE company_code=? AND document_sn=? AND line_key=?",q,c,sn,key);journal(c,sn,s(cmd,"message_id")+"/"+key,"TRANSFER_OUT",b,type,-q,s(cmd,"actor"));}
   else{need(q<=n(h,"out_quantity")-n(h,"in_quantity")-n(h,"recovered_quantity"),"目的实收或原仓收回超过实际出库后的在途余额");String store=s(h,action.equals("in")?"target_store":"source_store");jdbc.update("INSERT INTO wms_inventory(company_code,sku_sn,store_code,version) VALUES (?,?,?,1) ON DUPLICATE KEY UPDATE id=id",c,sku,store);consistent(c,sku,store);jdbc.update("INSERT INTO wms_inventory_batch(company_code,sku_sn,store_code,batch_code,transaction_price,version) VALUES (?,?,?,?,?,1) ON DUPLICATE KEY UPDATE id=id",c,sku,store,h.get("batch_code"),h.get("unit_cost"));Map<String,Object>b=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=? AND batch_code=? FOR UPDATE",c,sku,store,h.get("batch_code"));need(new BigDecimal(b.get("transaction_price").toString()).compareTo(new BigDecimal(h.get("unit_cost").toString()))==0,"目的批次同名但成本不同，请先核对批次资料");change(c,b,type,q,q,0);summary(c,sku,q,type.equals("ZP")?q:0,0,type.equals("CP")?q:0);String column=action.equals("in")?"in_quantity":"recovered_quantity";jdbc.update("UPDATE oms_stock_transfer_line SET "+column+"="+column+"+? WHERE company_code=? AND document_sn=? AND line_key=?",q,c,sn,key);journal(c,sn,s(cmd,"message_id")+"/"+key,action.equals("in")?"TRANSFER_IN":"TRANSFER_RECOVER",b,type,q,s(cmd,"actor"));OrderStockService.replanPending(jdbc,c,sku);}
  }
 }
 /** Independent reviewed adjustment. Validate the entire real-warehouse snapshot under SKU locks, never just its chosen virtual bin. */
 private void adjust(String c,String sn,Map<String,Object>cmd){need(sn.startsWith("TZ")&&!s(cmd,"evidence").isEmpty(),"调整需要独立单号及盘点凭证");List<Map<String,Object>>lines=rows(cmd.get("lines"));need(!lines.isEmpty()&&lines.size()<=200,"调整明细须为1至200行");Map<String,Object>expected=object(cmd.get("snapshot"));lock(c,rows(expected.get("totals")));if(prior(c,sn,"ADJUST",cmd))return;Map<String,Object>current=snapshot(c,expected);need(versions(expected).equals(versions(current)),"对账后库存已变化，请重新对账并重新申请调整");Set<String>seen=new HashSet<>();
  for(Map<String,Object>l:lines){String sku=s(l,"sku_sn"),store=s(l,"store_code"),type=s(l,"inventory_type");long q=n(l,"quantity");need(q!=0&&q>=-100000000&&q<=100000000&&strings(expected.get("stores"),50).contains(store)&&strings(expected.get("skus"),100).contains(sku)&&Arrays.asList("ZP","CP").contains(type)&&seen.add(store+"/"+sku+"/"+s(l,"batch_code")+"/"+type),"调整范围、批次质量或差量无效");jdbc.update("INSERT INTO wms_inventory(company_code,sku_sn,store_code,version) VALUES (?,?,?,1) ON DUPLICATE KEY UPDATE id=id",c,sku,store);consistent(c,sku,store);need(l.get("unit_cost")!=null,"盘盈须明确成本来源");jdbc.update("INSERT INTO wms_inventory_batch(company_code,sku_sn,store_code,batch_code,transaction_price,version) VALUES (?,?,?,?,?,1) ON DUPLICATE KEY UPDATE id=id",c,sku,store,l.get("batch_code"),l.get("unit_cost"));Map<String,Object>b=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=? AND batch_code=? FOR UPDATE",c,sku,store,l.get("batch_code"));need(new BigDecimal(b.get("transaction_price").toString()).compareTo(new BigDecimal(l.get("unit_cost").toString()))==0,"原批次成本变化");if(q<0&&type.equals("ZP"))need(mutations.allocationAvailable(c,sku,Collections.singletonList(store))>=-q,"盘亏不能消耗订单预占或福袋保障库存");change(c,b,type,q,q,0);summary(c,sku,q,type.equals("ZP")?q:0,0,type.equals("CP")?q:0);journal(c,sn,"ADJUST",q>0?"COUNT_GAIN":"COUNT_LOSS",b,type,q,s(cmd,"actor"));OrderStockService.replanPending(jdbc,c,sku);}
  record(c,sn,"ADJUST",cmd);
 }
}
